const query = String(input.query || '').trim();
const limit = Math.max(1, Math.min(Number(input.limit) || 5, 10));
const fallbackPage = 'https://developer.mozilla.org/en-US/search?q=' + encodeURIComponent(query);
const origin = typeof location !== 'undefined' && typeof location.origin === 'string' && /^https:\/\/developer\.mozilla\.org$/i.test(location.origin) ? location.origin : '';
if (!origin) {
  return { success: false, status: 'page_not_ready', query, message: 'MDN page origin is not ready', source: fallbackPage };
}
const endpoint = new URL('/api/v1/search', origin);
endpoint.searchParams.set('q', query);
endpoint.searchParams.set('locale', 'en-US');
const pageUrl = typeof location.href === 'string' && location.href.startsWith(origin) ? location.href : fallbackPage;
let response;
try {
  response = await fetch(endpoint.href, { credentials: 'include', headers: { Accept: 'application/json' } });
} catch (error) {
  return { success: false, status: 'fetch_error', query, message: String(error && error.message || error), source: endpoint.href };
}
if (response.status === 429) {
  return { success: false, status: 'rate_limited', query, httpStatus: 429, source: response.url || endpoint.href };
}
if (!response.ok) return { success: false, status: 'http_error', query, httpStatus: response.status, source: response.url || endpoint.href };
let data;
try {
  data = await response.json();
} catch {
  return { success: false, status: 'invalid_json', query, source: response.url || endpoint.href };
}
if (!data || typeof data !== 'object') {
  return { success: false, status: 'schema_changed', query, source: response.url || endpoint.href };
}
const documents = (Array.isArray(data.documents) ? data.documents : [])
  .filter(item => item && typeof item.mdn_url === 'string' && item.mdn_url.startsWith('/'))
  .map(item => ({
    title: String(item.title || '').replace(/<[^>]*>/g, '').trim(),
    url: new URL(item.mdn_url, origin).href,
    summary: String(item.summary || '').replace(/<[^>]*>/g, '').trim()
  }))
  .filter(item => item.title && /^https:\/\/developer\.mozilla\.org\/[a-z]{2}(?:-[A-Z]{2})?\/docs\//.test(item.url))
  .slice(0, limit);
if (!documents.length) {
  return {
    success: true,
    status: 'empty',
    query,
    documents: [],
    sources: { api: response.url || endpoint.href, page: pageUrl },
    total: 0
  };
}
return {
  success: true,
  status: 'ok',
  query,
  documents,
  sources: { api: response.url || endpoint.href, page: pageUrl },
  total: Math.max(documents.length, Math.floor(Number(data.metadata && data.metadata.total && data.metadata.total.value) || documents.length))
};
